import fs from "node:fs";
import path from "node:path";
import process from "node:process";
import { areas, project } from "./site-data.mjs";

const root = process.cwd();
const out = path.join(root, "site");
const config = JSON.parse(fs.readFileSync(path.join(root, "site.config.json"), "utf8"));
const base = config.baseUrl.replace(/\/$/, "");
const routes = [];
const serviceBySlug = Object.fromEntries(project.services.map((service) => [service.slug, service]));
const serviceGroups = [...new Set(project.services.map((service) => service.group))];
const areaGroups = [...new Set(areas.map((area) => area.region))];
const esc = (value) => String(value).replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;").replaceAll("'", "&#39;");
const abs = (route) => `${base}${route}`;
const serviceRoute = (service) => `/services/${service.slug}/`;
const areaRoute = (area) => `/service-areas/${area.slug}/`;
const localRoute = (service, area) => `${areaRoute(area)}${service.slug}/`;
const localH1 = (service, area) => `${service.label} in ${area.label}`;
const areaH1 = (area) => `${project.topic} Services in ${area.label}`;

function resetGeneratedPages() {
  for (const relative of ["services", "service-areas", "process", "contact", "privacy"]) fs.rmSync(path.join(out, relative), { recursive: true, force: true });
  for (const relative of ["index.html", "404.html", "sitemap.xml", "robots.txt"]) fs.rmSync(path.join(out, relative), { force: true });
  fs.mkdirSync(path.join(out, "assets"), { recursive: true });
}

function write(route, html) {
  const relative = route === "/" ? "index.html" : route === "/404.html" ? "404.html" : `${route.replace(/^\//, "")}index.html`;
  const file = path.join(out, relative);
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, html, "utf8");
  if (route !== "/404.html") routes.push(route);
}

function image({ service = null, area = null, eager = false, className = "content-photo" } = {}) {
  const alt = service ? `${service.label} planning for ${area ? `${area.label} properties` : "Greater Houston properties"}` : project.heroImageAlt;
  return `<figure class="${className}"><img src="/assets/images/${project.heroImage}" alt="${esc(alt)}" width="${project.heroWidth}" height="${project.heroHeight}" loading="${eager ? "eager" : "lazy"}" decoding="async"${eager ? ' fetchpriority="high"' : ""}></figure>`;
}

function brand() {
  const pipeIcon = `<svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M7 7h8v7h10v11H14v-8H7V7Z" stroke="currentColor" stroke-width="3" stroke-linejoin="round"/><path d="M20 14v11" stroke="var(--orange)" stroke-width="3" stroke-linecap="round"/></svg>`;
  return `<a class="brand" href="/" aria-label="${esc(project.name)} home"><span class="mark">${pipeIcon}</span><span class="brand-copy"><strong>${esc(project.name)}</strong><small>Greater Houston ${esc(project.topic)}</small></span></a>`;
}

function menuGroups(items, groupKey, routeFor) {
  return [...new Set(items.map((item) => item[groupKey]))].map((group) => `<div class="menu-group"><strong>${esc(group)}</strong>${items.filter((item) => item[groupKey] === group).map((item) => `<a href="${routeFor(item)}">${esc(item.label)}</a>`).join("")}</div>`).join("");
}

function header(active = "") {
  return `<a class="skip" href="#main-content">Skip to content</a><div class="status"><div class="shell"><span></span><p>Independent Greater Houston service-request resource</p><b>Exact operator availability confirmed after intake</b></div></div><header class="header"><div class="shell nav-shell">${brand()}<button class="menu-toggle" type="button" aria-expanded="false" aria-controls="site-nav" aria-label="Open navigation"><i></i><i></i><i></i></button><nav class="site-nav" id="site-nav" aria-label="Primary navigation"><div class="dropdown"><div class="dropdown-control"><a href="/services/"${active === "services" ? ' aria-current="page"' : ""}>Services</a><button type="button" aria-expanded="false" aria-label="Toggle services menu">+</button></div><div class="mega mega-services">${menuGroups(project.services, "group", serviceRoute)}</div></div><div class="dropdown"><div class="dropdown-control"><a href="/service-areas/"${active === "areas" ? ' aria-current="page"' : ""}>Service Areas</a><button type="button" aria-expanded="false" aria-label="Toggle service areas menu">+</button></div><div class="mega mega-areas">${menuGroups(areas, "region", areaRoute)}</div></div><a href="/process/"${active === "process" ? ' aria-current="page"' : ""}>Process</a><a href="/contact/"${active === "contact" ? ' aria-current="page"' : ""}>Contact</a><a class="button nav-cta" href="/contact/#request">${esc(project.requestLabel)}</a></nav></div></header>`;
}

function footer() {
  return `<footer class="footer"><div class="shell footer-top"><div>${brand()}<p>An independent rank-and-rent information and request property. This website does not claim a storefront, Google Business Profile, contractor license, or guaranteed dispatch.</p></div><nav aria-label="Footer utility"><strong>Site</strong><a href="/services/">Services</a><a href="/service-areas/">Service Areas</a><a href="/process/">Process</a><a href="/contact/">Contact</a><a href="/privacy/">Privacy</a></nav><div><strong>Request status</strong><p>Forms route to HubSpot for intake. A qualified provider, exact ZIP-code coverage, scope, price, and schedule must be confirmed before work is arranged.</p></div></div><div class="shell footer-dir"><h2>${esc(project.topic)} services</h2><div class="footer-grid service-footer">${serviceGroups.map((group) => `<nav><strong>${esc(group)}</strong>${project.services.filter((service) => service.group === group).map((service) => `<a href="${serviceRoute(service)}">${esc(service.label)}</a>`).join("")}</nav>`).join("")}</div></div><div class="shell footer-dir"><h2>Greater Houston service-area guides</h2><div class="footer-grid area-footer">${areaGroups.map((group) => `<nav><strong>${esc(group)}</strong>${areas.filter((area) => area.region === group).map((area) => `<a href="${areaRoute(area)}">${esc(area.label)}</a>`).join("")}</nav>`).join("")}</div></div><div class="shell footer-bottom"><span>© ${new Date().getFullYear()} ${esc(project.name)}</span><span>Independent service-request website</span></div></footer><a class="mobile-lead-cta" href="/contact/#request">${esc(project.requestLabel)}</a>`;
}

const breadcrumb = (items) => ({ "@type": "BreadcrumbList", itemListElement: items.map((item, index) => ({ "@type": "ListItem", position: index + 1, name: item.name, item: abs(item.route) })) });
const crumbs = (items) => `<nav class="crumbs" aria-label="Breadcrumb">${items.map((item) => item.route ? `<a href="${item.route}">${esc(item.label)}</a><span>/</span>` : `<b aria-current="page">${esc(item.label)}</b>`).join("")}</nav>`;
function faq(title, intro, items) { return `<section class="section faq" aria-labelledby="faq-title"><div class="shell faq-grid"><div><p class="eyebrow">Frequently asked questions</p><h2 id="faq-title">${esc(title)}</h2><p>${esc(intro)}</p></div><div class="accordion">${items.map(([q, a]) => `<details><summary>${esc(q)}<span aria-hidden="true">+</span></summary><p>${esc(a)}</p></details>`).join("")}</div></div></section>`; }
const faqSchema = (items) => ({ "@type": "FAQPage", mainEntity: items.map(([q, a]) => ({ "@type": "Question", name: q, acceptedAnswer: { "@type": "Answer", text: a } })) });

function quickForm(service = null, area = null, instance = "hero") {
  const id = `request-${instance}`;
  return `<form class="quick-lead" id="${id}" data-lead-form novalidate><div class="quick-lead-head"><p class="eyebrow">Service request</p><h2>Describe the property and problem</h2><span>Share enough detail to review provider fit and the likely next step.</span></div><div class="quick-fields"><div class="field"><label for="${id}-name">Name</label><input id="${id}-name" name="name" autocomplete="name" required><span data-error-for="name"></span></div><div class="field"><label for="${id}-contact">Email or phone</label><input id="${id}-contact" name="contact" autocomplete="email" required><span data-error-for="contact"></span></div><div class="field"><label for="${id}-location">Property location</label><input id="${id}-location" name="location" autocomplete="street-address" value="${area ? esc(area.label) : ""}" required><span data-error-for="location"></span></div><div class="field"><label for="${id}-service">Closest service</label><select id="${id}-service" name="service" required><option value="">Select a service</option>${project.services.map((item) => `<option value="${item.slug}"${service?.slug === item.slug ? " selected" : ""}>${esc(item.label)}</option>`).join("")}</select><span data-error-for="service"></span></div><div class="field full"><label for="${id}-details">What is happening?</label><textarea id="${id}-details" name="details" rows="3" required placeholder="Symptoms, affected areas, timing, prior work, access, and scheduling needs"></textarea><span data-error-for="details"></span></div><div class="honeypot" aria-hidden="true"><label>Company<input name="company" tabindex="-1" autocomplete="off"></label></div></div><p class="quick-note">Secure requests are sent to HubSpot for lead intake. Do not include payment details, access codes, or sensitive information.</p><button class="button" type="submit">Send Service Request</button><div class="form-status" role="status" aria-live="polite" data-form-status></div></form>`;
}

function finalCta(title, copy) { return `<section class="final-cta"><div class="shell"><div><p class="eyebrow">Prepare the request</p><h2>${esc(title)}</h2></div><div><p>${esc(copy)}</p><a class="button button-light" href="/contact/#request">${esc(project.requestLabel)}</a></div></div></section>`; }
function pageHero({ h1, eyebrow, intro, trail, service = null, area = null }) { return `<section class="page-hero"><div class="shell">${crumbs(trail)}<div class="page-hero-grid"><div class="page-title"><p class="eyebrow">${esc(eyebrow)}</p><h1>${esc(h1)}</h1><p class="hero-intro">${esc(intro)}</p>${image({ service, area, className: "hero-photo" })}</div>${quickForm(service, area, "hero")}</div></div></section>`; }
function serviceCards(items, routeFor = serviceRoute, area = null) { return items.map((service) => `<a class="service-card" href="${routeFor(service)}">${image({ service, area, className: "card-photo" })}<span>${esc(service.group)}</span><h3>${esc(service.label)}</h3><p>${esc(service.intro)}.</p><b>Explore ${esc(service.label.toLowerCase())} →</b></a>`).join(""); }

function page({ title, description, route, body, active = "", graph = [] }) {
  const robots = route === "/404.html" ? "noindex, follow" : config.indexingEnabled ? "index, follow" : "noindex, nofollow";
  const schema = { "@context": "https://schema.org", "@graph": [{ "@type": "WebSite", name: project.name, url: abs("/"), description: `Independent Greater Houston ${project.topicLower} information and service-request resource.` }, ...graph] };
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><meta name="description" content="${esc(description)}"><meta name="robots" content="${robots}"><link rel="canonical" href="${abs(route)}"><meta property="og:type" content="website"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${abs(route)}"><meta property="og:site_name" content="${esc(project.name)}"><meta property="og:image" content="${abs(`/assets/images/${project.heroImage}`)}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/styles.css"><script type="application/ld+json">${JSON.stringify(schema)}</script><script src="/assets/main.js" defer></script><script src="/assets/lead-routing.js" data-site="${esc(project.name)}" data-phone="${esc(config.phone || "")}" defer></script></head><body>${header(active)}${body}${footer()}</body></html>`;
}

function serviceFaqs(service) {
  return [
    [`What information helps with ${service.label.toLowerCase()}?`, `Share the property type, first symptom, timing, affected fixtures or zones, prior work, known pipe material, access limits, and any inspection, photo, or video already available.`],
    [`What does the service scope need to identify?`, `A useful proposal identifies ${service.system}. It should distinguish included plumbing work from excavation, finish removal, restoration, engineering, utility work, and other trades.`],
    [`Which methods may be considered?`, `The work may involve ${service.methods}. The correct sequence depends on verified conditions at the property and the qualifications of the selected operator.`],
    [`What documentation should be requested?`, `Ask for ${service.evidence}. Written limits make bids easier to compare and reduce confusion about access, cleanup, inspection, and restoration.`],
    [`What changes the cost of ${service.label.toLowerCase()}?`, `Pricing commonly changes with ${service.costFactors}. A written estimate should state assumptions, exclusions, change-order rules, and payment milestones.`]
  ];
}

function areaFaqs(area) {
  return [
    [`Is ${area.label} guaranteed to have an available provider?`, `No. ${area.label} is an intended request market. The exact address, ZIP code, service, timing, access, and provider coverage must be confirmed before scheduling.`],
    [`What property details matter in ${area.label}?`, `${area.propertyMix} Share the building type, construction, occupancy, pipe routes, affected areas, and who controls access.`],
    [`Why is the exact ${area.label} address needed?`, `Local names can cross city, county, utility, MUD, inspection, and private-property boundaries. The address helps identify the correct jurisdiction and service responsibility.`],
    [`How should access be prepared in ${area.label}?`, area.access],
    [`Does this website claim a local office in ${area.label}?`, `No. The site does not publish an unverified storefront, service base, Google Business Profile, staff, license, or provider identity for ${area.label}.`]
  ];
}

function localFaqs(service, area) {
  return [
    [`Is ${service.label.toLowerCase()} active in ${area.label} now?`, `This page maps a requested service to an intended market. A qualified operator must verify the exact ${area.label} address, scope, availability, license responsibility, and schedule.`],
    [`What should be documented before requesting this service?`, `Record the first symptom, when it occurs, affected fixtures or buildings, prior work, pipe material if known, photos or videos, and the property access conditions.`],
    [`Which local conditions can affect the scope?`, `${area.waterContext} These conditions influence diagnosis, routing, access, excavation, shutdown planning, and restoration but do not prove a particular failure.`],
    [`What should the written ${area.label} proposal contain?`, `It should identify ${service.evidence}, plus the exact address, provider identity, license responsibility, price, exclusions, schedule, permits, inspection, cleanup, and warranty terms.`],
    [`What can change the price in ${area.label}?`, `The main service variables are ${service.costFactors}. Local access, distance, occupied-space coordination, security, jurisdiction, and changed field conditions can also affect the total.`]
  ];
}

function homePage() {
  const matrixCount = project.services.length * areas.length;
  const faqs = [
    [`Which ${project.topicLower} service should I choose?`, `Start with the closest problem or decision: the complete system, a material-specific option, an inspection need, a repair method, or a managed-property scope. The intake can be corrected after the conditions are reviewed.`],
    [`Does this website perform the plumbing work?`, `No. This is an independent service-request website. A qualified provider, exact coverage, credentials, scope, price, and schedule must be confirmed before work is arranged.`],
    [`Are all ${areas.length} Greater Houston markets active?`, `They are intended request markets. Exact service and ZIP-code coverage must be confirmed with the selected operator for each property.`],
    ["Where do form requests go?", "Valid form submissions are sent to HubSpot for lead intake and follow-up. Submission does not guarantee immediate dispatch or provider acceptance."],
    ["Are licenses, reviews, warranties, or prices claimed?", "No unverified license, review, staff, project-history, warranty, fixed-price, or ranking claim is published. Those facts must come from the eventual operator and written proposal."]
  ];
  const coreSlugs = ["houston", "katy", "the-woodlands", "cypress", "sugar-land", "pearland", "league-city", "pasadena"];
  const coreAreas = coreSlugs.map((slug) => areas.find((area) => area.slug === slug)).filter(Boolean);
  const body = `<main id="main-content"><section class="home-hero"><div class="shell home-grid"><div class="home-copy"><p class="eyebrow">Greater Houston ${esc(project.topicLower)}</p><h1>${esc(project.homepageH1)}</h1><p class="lede">${esc(project.lede)}</p><div class="actions"><a class="button" href="#request-home">${esc(project.requestLabel)}</a><a href="/services/">Explore all ${project.services.length} services</a></div><ul><li>${project.services.length} focused service scopes</li><li>${areas.length} Greater Houston market guides</li><li>${matrixCount} one-to-one city and service pages</li></ul></div><div class="home-convert">${image({ eager: true, className: "home-photo" })}${quickForm(null, null, "home")}</div></div></section><section class="section intro"><div class="shell split"><div><p class="eyebrow">Start with the actual system</p><h2>Match the property condition to a useful service scope</h2></div><div class="prose"><p>The same symptom can lead to very different work depending on pipe material, route, access, depth, occupancy, prior repairs, and the part of the system that has actually failed.</p><p>This site separates service intents so each request can carry the right questions, documentation needs, cost variables, related services, and location-specific planning details.</p></div></div></section><section class="section"><div class="shell section-head"><div><p class="eyebrow">${esc(project.topic)} services</p><h2>Focused planning and request paths</h2></div><a href="/services/">Complete service directory</a></div><div class="shell card-grid">${serviceCards(project.services)}</div></section><section class="section evidence"><div class="shell section-head"><div><p class="eyebrow">Scope before commitment</p><h2>Inspect, compare, document</h2></div><p>A strong request separates symptoms from confirmed conditions, defines the plumbing boundary, and asks for a written method, price, exclusions, and verification plan.</p></div><div class="shell evidence-grid"><article><span>01</span><h3>Describe the condition</h3><p>Record symptoms, timing, affected fixtures or buildings, prior work, and any photos, video, or test results already available.</p></article><article><span>02</span><h3>Define the system</h3><p>Identify pipe material, route, access, utility or property boundary, occupancy, and the connections included in the proposed work.</p></article><article><span>03</span><h3>Compare written scopes</h3><p>Review method, materials, permits, inspection, shutdowns, restoration, exclusions, change orders, and verification before authorizing work.</p></article></div></section><section class="section dark"><div class="shell split"><div><p class="eyebrow">Greater Houston market architecture</p><h2>City pages connect to city-specific services</h2></div><div class="prose"><p>Every approved market guide links to the matching local version of every service. Local related-service links stay inside the same market instead of sending every visitor back to a generic Houston page.</p><a class="button" href="/service-areas/">Browse all ${areas.length} markets</a></div></div><div class="shell core-location-grid">${coreAreas.map((area) => `<a href="${areaRoute(area)}"><span>${esc(area.region)}</span><h3>${esc(area.label)}</h3><p>${esc(area.context)}</p><b>${esc(project.topic)} in ${esc(area.label)} →</b></a>`).join("")}</div></section>${faq(`${project.topic} questions for Greater Houston`, "Website status, service selection, local coverage, form routing, and verification.", faqs)}${finalCta(`Prepare a ${project.topicLower} request.`, "Share the property location, system condition, affected areas, timing, prior work, available documentation, and access details.")}</main>`;
  return page({ title: project.homepageH1, description: `Explore Greater Houston ${project.topicLower} services, decision guidance, and one-to-one city pages with a secure HubSpot request form.`, route: "/", body, graph: [faqSchema(faqs)] });
}

function servicesPage() {
  const faqs = [["Why are these services separated?", "Each page addresses a distinct system decision, method, material, property type, or inspection need so visitors can reach the most useful scope."],["Can one project involve several pages?", "Yes. Inspection, repair, replacement, access, materials, and restoration decisions may connect, but each written proposal should still identify its exact scope."],["Does a request create a contract?", "No. A form submission is only an intake request. Provider acceptance, credentials, terms, price, and authorization require separate confirmation."],["Are prices listed?", "No fixed prices are published because access, material, length, depth, building size, permits, restoration, and field conditions change the scope."],["How are local pages connected?", "Every service page links to its city-specific counterpart in each mapped market, and those local pages link back to related services in the same market."]];
  const body = `<main id="main-content">${pageHero({ h1: `${project.topic} Service Directory`, eyebrow: `${project.services.length} mapped service scopes`, intro: "Choose the service that best matches the confirmed condition, material, method, property type, or next decision.", trail: [{label:"Home",route:"/"},{label:"Services"}] })}<section class="section"><div class="shell">${serviceGroups.map((group) => `<section class="directory-group"><div><p class="eyebrow">Service category</p><h2>${esc(group)}</h2></div><div class="directory-list">${project.services.filter((service) => service.group === group).map((service) => `<a href="${serviceRoute(service)}"><span>${esc(service.label)}</span><small>${esc(service.scope)}</small><b>→</b></a>`).join("")}</div></section>`).join("")}</div></section>${faq(`${project.topic} service-directory questions`, "How to select, compare, and route the listed service scopes.", faqs)}${finalCta("Start with the closest service scope.", "The intake can be refined after the property, system, documentation, and provider fit are reviewed.")}</main>`;
  return page({ title: `${project.topic} Service Directory`, description: `Compare ${project.services.length} Greater Houston ${project.topicLower} services, related decisions, documentation needs, and matched service-area pages.`, route: "/services/", body, active: "services", graph: [breadcrumb([{name:"Home",route:"/"},{name:"Services",route:"/services/"}]), faqSchema(faqs)] });
}

function serviceContent(service) {
  return `<div data-unique-copy><section class="section"><div class="shell content-grid"><article class="prose"><p class="eyebrow">Service scope</p><h2>When ${esc(service.label.toLowerCase())} may fit</h2><p>${esc(service.baseH1)} is intended to ${esc(service.intro)}. It may be relevant when ${esc(service.situation)}. These symptoms start the investigation, but the property conditions and available documentation must support the final recommendation.</p><p>The working system includes ${esc(service.system)}. A proposal that skips those boundaries can leave important connections, testing, access, or restoration outside the price without making that limitation obvious.</p><h2>Inspection and method selection</h2><p>The work may involve ${esc(service.methods)}. Not every property needs every step. The operator should explain which observations support the selected method, what remains uncertain, and what additional access or testing could change the recommendation.</p>${image({ service })}<h2>What a written scope should document</h2><p>Ask for ${esc(service.evidence)}. The estimate should also identify the company and Responsible Master Plumber, insurance status, permit responsibility, inspection, cleanup, protection, start assumptions, schedule, payment milestones, exclusions, change-order method, and warranty terms.</p><h2>Repair, access, and restoration boundaries</h2><p>${esc(service.decision)}. Plumbing, excavation, demolition, structural work, remediation, drywall, painting, flooring, landscaping, paving, and utility work may be performed by different parties. The proposal should state which party owns each boundary.</p><h2>Cost and comparison variables</h2><p>Pricing commonly changes with ${esc(service.costFactors)}. Compare bids by scope and evidence rather than price alone. A lower number can exclude restoration, permits, testing, reconnections, disposal, or work that another proposal includes.</p><h2>Preparing the property and request</h2><p>Gather the exact address, property type, occupancy, first symptom, timing, affected fixtures or buildings, prior repairs, known material, available photos or video, utility or MUD information, parking, gates, pets, tenant contacts, and acceptable shutdown windows. Do not share access codes or payment data in the web form.</p></article><aside class="scope-card"><span>Scope snapshot</span><h2>${esc(service.label)}</h2><dl><dt>Service goal</dt><dd>${esc(service.intro)}</dd><dt>System</dt><dd>${esc(service.system)}</dd><dt>Approach</dt><dd>${esc(service.methods)}</dd><dt>Documentation</dt><dd>${esc(service.evidence)}</dd></dl><a class="button" href="#request-hero">Prepare Request</a></aside></div></section></div>`;
}

function servicePage(service) {
  const faqs = serviceFaqs(service);
  const related = service.related.map((slug) => serviceBySlug[slug]);
  const body = `<main id="main-content">${pageHero({ h1: service.baseH1, eyebrow: service.group, intro: `${service.label} guidance for Greater Houston properties, including scope, method, documentation, access, and cost variables.`, trail: [{label:"Home",route:"/"},{label:"Services",route:"/services/"},{label:service.label}], service })}${serviceContent(service)}<section class="section related"><div class="shell section-head"><div><p class="eyebrow">Related service paths</p><h2>Related ${esc(project.topic)} Services</h2></div><p>Use the related scope that matches the confirmed system, method, material, or next decision.</p></div><div class="shell card-grid related-grid">${serviceCards(related)}</div></section><section class="section"><div class="shell section-head"><div><p class="eyebrow">City-matched guides</p><h2>${esc(service.label)} Service Areas</h2></div><p>Each link opens the one-to-one local page for this service and market.</p></div><div class="shell link-groups">${areaGroups.map((group) => `<div><strong>${esc(group)}</strong>${areas.filter((area) => area.region === group).map((area) => `<a href="${localRoute(service, area)}">${esc(service.label)} in ${esc(area.label)}</a>`).join("")}</div>`).join("")}</div></section>${faq(`${service.label} questions`, `Scope, methods, documentation, boundaries, and cost variables for ${service.label.toLowerCase()}.`, faqs)}${finalCta(`Prepare a ${service.label.toLowerCase()} request.`, "Include the exact property, symptoms, known material, prior work, available inspection evidence, access, and timing.")}</main>`;
  return page({ title: service.baseH1, description: `${service.baseH1}: compare scope, methods, documentation, cost variables, related services, and matched Greater Houston market pages.`, route: serviceRoute(service), body, active: "services", graph: [breadcrumb([{name:"Home",route:"/"},{name:"Services",route:"/services/"},{name:service.label,route:serviceRoute(service)}]), faqSchema(faqs)] });
}

function nearbyAreas(area) {
  const index = areas.findIndex((item) => item.slug === area.slug);
  return [areas[(index - 2 + areas.length) % areas.length], areas[(index - 1 + areas.length) % areas.length], areas[(index + 1) % areas.length], areas[(index + 2) % areas.length]];
}

function areasPage() {
  const faqs = [["Are these offices or physical locations?", "No. They are intended request-market guides. The website does not claim a storefront, staff, address, or Google Business Profile in these places."],["Why include city-specific pages?", "Property mix, access, utilities, municipal boundaries, occupancy, and local logistics can change how a request should be prepared and routed."],["Does every provider serve every market?", "No. Exact ZIP-code and service coverage must be confirmed with the eventual provider before scheduling."],["How do city pages link to services?", "Each market guide links to its own matched version of every service rather than sending all visitors to a generic Houston service page."],["What should I submit with the location?", "Share the exact city and ZIP, property type, symptom, system or material if known, prior work, access constraints, and preferred timing."]];
  const body = `<main id="main-content">${pageHero({ h1: `${project.topic} Service Areas`, eyebrow: `${areas.length} intended Greater Houston markets`, intro: "Browse city, community, neighborhood, and district guides with one-to-one pages for every mapped service.", trail: [{label:"Home",route:"/"},{label:"Service Areas"}] })}<section class="section"><div class="shell">${areaGroups.map((group) => `<section class="area-region"><div class="section-head"><div><p class="eyebrow">Greater Houston region</p><h2>${esc(group)}</h2></div><span>${areas.filter((area) => area.region === group).length} market guides</span></div><div class="location-grid">${areas.filter((area) => area.region === group).map((area) => `<a href="${areaRoute(area)}"><span>${esc(area.type)} · ${esc(area.county)}</span><h3>${esc(area.label)}</h3><p>${esc(area.context)}</p><b>${esc(project.topic)} in ${esc(area.label)} →</b></a>`).join("")}</div></section>`).join("")}</div></section>${faq("Greater Houston service-area questions", "Coverage status, local context, matched service pages, and request details.", faqs)}${finalCta("Start with the exact property location.", "Share the city, ZIP code, property type, system condition, prior work, access limits, and preferred timing.")}</main>`;
  return page({ title: `${project.topic} Service Areas`, description: `Browse ${areas.length} Greater Houston ${project.topicLower} market guides with one-to-one local pages for all ${project.services.length} mapped services.`, route: "/service-areas/", body, active: "areas", graph: [breadcrumb([{name:"Home",route:"/"},{name:"Service Areas",route:"/service-areas/"}]), faqSchema(faqs)] });
}

function areaContent(area) {
  return `<div data-unique-copy><section class="section"><div class="shell content-grid"><article class="prose"><p class="eyebrow">${esc(area.label)} property guide</p><h2>Property and plumbing context in ${esc(area.label)}</h2><p>${esc(area.context)}</p><p>${esc(area.propertyMix)} These differences can change pipe routes, access, shutdowns, utility responsibility, restoration, and the number of systems that must be considered before a provider prepares a price.</p><h2>Local conditions that can change the request</h2><p>${esc(area.waterContext)} Those conditions do not prove a specific plumbing failure. They help explain why the exact property, system, material, prior work, and available inspection evidence matter.</p>${image({ area })}<h2>Preparing a ${esc(area.label)} property</h2><p>${esc(area.access)}</p><p>Before requesting service, record the first symptom, timing, affected fixtures or buildings, known pipe material, prior repairs, recent construction, municipal or MUD information, tenant or manager approvals, parking, gates, pets, and acceptable shutdown windows.</p><h2>Provider and jurisdiction verification</h2><p>The responsible provider, plumbing license, insurance, permit authority, inspection process, utility boundary, and exact ZIP-code coverage must be verified for the property. This website does not claim an office or operator in ${esc(area.label)}.</p><h2>How the local service pages work</h2><p>The links below stay inside ${esc(area.label)}. Each destination combines one approved service with this market's property, access, and infrastructure context, then links to related services in ${esc(area.label)} and the same service in nearby markets.</p></article><aside class="content-lead">${quickForm(null, area, "content")}</aside></div></section></div>`;
}

function areaPage(area) {
  const h1 = areaH1(area);
  const faqs = areaFaqs(area);
  const body = `<main id="main-content">${pageHero({ h1, eyebrow: `${area.type} · ${area.county}`, intro: `${area.label} is an intended Greater Houston request market. Exact operator and property coverage require confirmation.`, trail: [{label:"Home",route:"/"},{label:"Service Areas",route:"/service-areas/"},{label:area.label}], area })}${areaContent(area)}<section class="section related"><div class="shell section-head"><div><p class="eyebrow">One-to-one local service pages</p><h2>${esc(project.topic)} Services in ${esc(area.label)}</h2></div><p>Every card links to its matching ${esc(area.label)} service page, not a generic Houston destination.</p></div><div class="shell card-grid">${serviceCards(project.services, (service) => localRoute(service, area), area)}</div></section><section class="section nearby"><div class="shell section-head"><div><p class="eyebrow">Nearby market guides</p><h2>Other intended markets near this service map</h2></div></div><div class="shell nearby-links">${nearbyAreas(area).map((nearby) => `<a href="${areaRoute(nearby)}">${esc(nearby.label)}</a>`).join("")}</div></section>${faq(`${area.label} ${project.topicLower} questions`, `Coverage, property details, access, provider verification, and local-service routing for ${area.label}.`, faqs)}${finalCta(`Prepare a ${project.topicLower} request for ${area.label}.`, "Include the exact property, affected system, first symptom, timing, prior work, documentation, and access details.")}</main>`;
  return page({ title: h1, description: `${h1}: local property context, ${project.services.length} city-matched services, access planning, provider verification, and secure request intake.`, route: areaRoute(area), body, active: "areas", graph: [breadcrumb([{name:"Home",route:"/"},{name:"Service Areas",route:"/service-areas/"},{name:area.label,route:areaRoute(area)}]), faqSchema(faqs)] });
}

function localContent(service, area) {
  return `<div data-unique-copy><section class="section"><div class="shell content-grid"><article class="prose"><p class="eyebrow">${esc(area.label)} service guide</p><h2>When this ${esc(area.label)} service may fit</h2><p>${esc(localH1(service, area))} is intended to ${esc(service.intro)}. The scope may fit when ${esc(service.situation)}. The reported condition starts the review but does not replace inspection, measurements, documentation, or a written provider recommendation.</p><p>${esc(area.propertyMix)} In this property mix, the request should identify the building type, occupancy, known pipe material, affected fixtures or structures, prior work, and who controls each access point or shutdown.</p><h2>Local conditions that can affect planning</h2><p>${esc(area.waterContext)} These conditions can change inspection, route selection, excavation, protection, shutdowns, and restoration. They do not prove the cause or authorize work without property-specific confirmation.</p>${image({ service, area })}<h2>System boundaries and service method</h2><p>The relevant system includes ${esc(service.system)}. The work may involve ${esc(service.methods)}. A qualified operator should explain which steps apply at the exact property, which conditions remain uncertain, and which discoveries can change the price or method.</p><h2>Documentation expected for the ${esc(area.label)} property</h2><p>Request ${esc(service.evidence)}. The record should also identify the provider, Responsible Master Plumber, insurance status, address, permit and inspection responsibility, included materials, schedule, shutdowns, cleanup, protection, exclusions, and warranty terms.</p><h2>Access and coordination in ${esc(area.label)}</h2><p>${esc(area.access)} For this service, also identify fixtures or branches affected, accessible shutoffs or cleanouts, finished surfaces, utilities, tenants, pets, security, work-hour limits, and the person authorized to approve changes.</p><h2>Method, restoration, and responsibility boundaries</h2><p>${esc(service.decision)} The proposal should distinguish plumbing from excavation, utility work, engineering, demolition, remediation, drywall, painting, flooring, paving, landscaping, and other restoration. The responsible party for each boundary must be clear before work starts.</p><h2>What affects cost in ${esc(area.label)}</h2><p>Core variables include ${esc(service.costFactors)}. Local travel, access, parking, security, jurisdiction, occupied-space coordination, after-hours work, and changed field conditions can also affect the total. Compare written scopes and evidence rather than headline prices alone.</p><h2>Preparing the request</h2><p>Share the exact ${esc(area.label)} address or ZIP code, property type, symptoms, known material, prior repairs, available images or video, municipal or MUD details, access limits, and preferred timing. Do not send payment information or security codes through the form.</p></article><aside class="scope-card"><span>${esc(area.label)} scope checklist</span><h2>${esc(service.label)}</h2><dl><dt>Service goal</dt><dd>${esc(service.intro)}</dd><dt>Property context</dt><dd>${esc(area.propertyMix)}</dd><dt>Method</dt><dd>${esc(service.methods)}</dd><dt>Documentation</dt><dd>${esc(service.evidence)}</dd></dl><a class="button" href="#request-hero">Prepare Request</a></aside></div></section></div>`;
}

function localPage(service, area) {
  const h1 = localH1(service, area);
  const faqs = localFaqs(service, area);
  const related = service.related.map((slug) => serviceBySlug[slug]);
  const body = `<main id="main-content">${pageHero({ h1, eyebrow: `${area.type} · Intended coverage pending verification`, intro: `${service.label} guidance for ${area.label} properties, with local access, system, scope, and cost considerations.`, trail: [{label:"Home",route:"/"},{label:"Service Areas",route:"/service-areas/"},{label:area.label,route:areaRoute(area)},{label:service.label}], service, area })}${localContent(service, area)}<section class="section related"><div class="shell section-head"><div><p class="eyebrow">Stay inside ${esc(area.label)}</p><h2>Related ${esc(project.topic)} Services in ${esc(area.label)}</h2></div><a href="${areaRoute(area)}">All ${esc(area.label)} services</a></div><div class="shell card-grid related-grid">${serviceCards(related, (item) => localRoute(item, area), area)}</div></section><section class="section nearby"><div class="shell section-head"><div><p class="eyebrow">Same service, nearby markets</p><h2>${esc(service.label)} Near ${esc(area.label)}</h2></div><a href="${serviceRoute(service)}">Greater Houston ${esc(service.label)}</a></div><div class="shell nearby-links">${nearbyAreas(area).map((nearby) => `<a href="${localRoute(service, nearby)}">${esc(service.label)} in ${esc(nearby.label)}</a>`).join("")}</div></section>${faq(`${service.label} in ${area.label}: questions`, `Local coverage, scope, documentation, access, and cost variables for this matched service page.`, faqs)}${finalCta(`Prepare a ${service.label.toLowerCase()} request for ${area.label}.`, "Share the exact location, property type, symptoms, known material, prior work, documentation, access, and preferred timing.")}</main>`;
  return page({ title: h1, description: `${h1}: local scope, methods, access, cost factors, and related city-matched services.`, route: localRoute(service, area), body, active: "areas", graph: [breadcrumb([{name:"Home",route:"/"},{name:"Service Areas",route:"/service-areas/"},{name:area.label,route:areaRoute(area)},{name:service.label,route:localRoute(service,area)}]), faqSchema(faqs)] });
}

function processPage() {
  const h1 = project.processTitle;
  const faqs = [["Does every request follow exactly the same steps?", "No. The sequence changes with the property, material, access, existing evidence, urgency, and the service that can actually resolve the confirmed condition."],["When should a camera, pressure test, or opening be approved?", "After the provider explains what the step can prove, its limitations, the access required, the price, and how the result affects the next decision."],["Who handles permits and inspections?", "The written proposal should name the responsible party and authority. Requirements depend on the exact address, jurisdiction, work type, and selected provider."],["How should competing proposals be compared?", "Compare included systems, materials, methods, access, permits, testing, restoration, exclusions, change orders, schedule, payment terms, and warranty language."],["When is work authorized?", "Only after the property owner or authorized manager accepts a verified provider's written scope and terms. A website form submission is not authorization."]];
  const steps = [["01","Describe the condition","Record symptoms, timing, affected fixtures or buildings, prior work, known material, and any inspection evidence already available."],["02","Verify the system","Identify pipe routes, access, utilities, property responsibility, occupancy, shutdown limits, and the components included in the decision."],["03","Inspect and compare methods","Use only the inspections needed to confirm condition and compare methods that fit the actual material, route, access, and jurisdiction."],["04","Define the written scope","Document materials, limits, connections, access openings, permits, testing, protection, cleanup, restoration, exclusions, and change orders."],["05","Complete and verify the work","Use the agreed sequence, maintain safe access, document changes, test the finished system, and obtain required inspection approval."],["06","Close restoration and records","Confirm cleanup, restoration responsibilities, final documentation, warranties, photos or video, and any maintenance or monitoring needs."]];
  const body = `<main id="main-content">${pageHero({ h1, eyebrow: "Scope before authorization", intro: project.processIntro, trail: [{label:"Home",route:"/"},{label:"Process"}] })}<section class="section"><div class="shell timeline">${steps.map(([n,t,c]) => `<article><span>${n}</span><div><h2>${esc(t)}</h2><p>${esc(c)}</p></div></article>`).join("")}</div></section>${faq(`${project.topic} process questions`, "Inspection, method selection, written scopes, permits, verification, and authorization.", faqs)}${finalCta("Prepare the property information before requesting a proposal.", "Share the exact location, system condition, known materials, prior work, inspection evidence, access, and timing.")}</main>`;
  return page({ title: h1, description: `${h1}: move from property symptoms and inspection through method selection, written scope, permits, work verification, and closeout.`, route: "/process/", body, active: "process", graph: [breadcrumb([{name:"Home",route:"/"},{name:"Process",route:"/process/"}]), faqSchema(faqs)] });
}

function contactPage() {
  const h1 = `Request ${project.topic} Service`;
  const faqs = [["Will someone follow up after submission?", "The form sends the request to HubSpot for lead intake and follow-up. Submission does not guarantee immediate dispatch, provider acceptance, or availability."],["Why is the location required?", "The city and ZIP code help check provider coverage, jurisdiction, travel, access, utility or MUD context, and the relevant local service page."],["What should be included in the description?", "Include symptoms, timing, affected fixtures or structures, known material, prior work, available photos or video, access, occupancy, and preferred timing."],["Should payment details or access codes be submitted?", "No. Do not include card or bank information, passwords, alarm codes, gate codes, medical information, or other sensitive data."],["Does submitting the form authorize work?", "No. Work requires a verified provider, written scope, price, terms, credentials, and separate authorization from the property owner or authorized manager."]];
  const body = `<main id="main-content">${pageHero({ h1, eyebrow: "Secure HubSpot lead intake", intro: "Send the property location, closest service, symptoms, timing, prior work, available evidence, and access details for follow-up.", trail: [{label:"Home",route:"/"},{label:"Contact"}] })}<section class="section" id="request"><div class="shell contact-grid"><div class="prose"><p class="eyebrow">Useful request details</p><h2>Describe what can be observed or documented</h2><p>Good intake details help distinguish an urgent symptom from the permanent service decision. Share facts you can see, hear, measure, photograph, or obtain from prior reports without guessing at the final diagnosis.</p><ul class="check-list"><li>Exact city and ZIP code</li><li>Property and occupancy type</li><li>First symptom and timing</li><li>Affected fixtures or buildings</li><li>Known material and route</li><li>Prior repairs or proposals</li><li>Photos, video, or reports</li><li>Access and shutdown limits</li></ul><h2>Independent request status</h2><p>This website is not the contractor. A provider's identity, Responsible Master Plumber, insurance, service area, scope, pricing, schedule, permits, inspection responsibility, and terms must be confirmed separately.</p></div>${quickForm(null, null, "contact")}</div></section>${faq(`${project.topic} request questions`, "Lead routing, useful details, sensitive information, and authorization boundaries.", faqs)}</main>`;
  return page({ title: h1, description: `Send a Greater Houston ${project.topicLower} request through secure HubSpot intake with the property, service, symptoms, prior work, and access details.`, route: "/contact/", body, active: "contact", graph: [breadcrumb([{name:"Home",route:"/"},{name:"Contact",route:"/contact/"}]), faqSchema(faqs)] });
}

function privacyPage() {
  const h1 = `Privacy Information for ${project.name}`;
  const faqs = [["What does the form collect?", "It may collect a name, contact method, property location, selected service, and situation details needed for lead intake and follow-up."],["Where is a valid form sent?", "The form sends submitted fields and the source page to HubSpot for lead intake. The browser does not intentionally store the request in local storage or cookies."],["Are calls recorded?", "No phone number is published until a controlled tracking line is assigned. If recording is enabled later, the privacy notice and caller disclosure must be updated first."],["Are analytics or advertising trackers installed?", "No general analytics, remarketing, advertising, or session-recording scripts are included in this static build."],["How can a data request be made?", "Use the website form and identify the submission you want accessed, corrected, or deleted. Do not include new sensitive information in the request."]];
  const body = `<main id="main-content"><section class="simple-hero"><div class="shell">${crumbs([{label:"Home",route:"/"},{label:"Privacy"}])}<p class="eyebrow">Lead and form data</p><h1>${esc(h1)}</h1><p>This page explains the current HubSpot form routing and the data boundaries for this independent service-request website.</p></div></section><section class="section"><article class="shell legal"><div data-unique-copy><h2>Information collected through forms</h2><p>The live request form may collect a name, email address or phone number, property location, selected service, and a description of the situation. After browser-side validation, those fields and the source page are sent to HubSpot for lead intake and follow-up.</p><h2>Purpose and potential provider sharing</h2><p>Submitted information is used to understand the request, check service and market fit, respond to the person who contacted the website, and maintain lead records. It may be available to the project owner, HubSpot, and a provider selected to review or fulfill the request.</p><h2>Sensitive information</h2><p>Do not submit payment-card details, bank information, passwords, alarm or gate codes, government identifiers, medical information, or other sensitive data. Share only the contact and property details reasonably needed to evaluate the request.</p><h2>Cookies, analytics, and calls</h2><p>No general analytics, remarketing, advertising, or session-recording scripts are included. A controlled phone line is not published in this build. If call tracking or recording is added, the visible disclosure and this page must be updated before activation.</p><h2>Retention, security, and requests</h2><p>Lead records are retained within the connected services according to the project owner's operational settings and applicable obligations. Use the contact form to request access, correction, or deletion and provide enough information to identify the original submission.</p></div></article></section>${faq("Privacy questions", "Current form collection, HubSpot routing, sensitive information, tracking, and data requests.", faqs)}</main>`;
  return page({ title: h1, description: `Read how ${project.name} sends service-request forms to HubSpot, limits sensitive data, and handles lead-routing and privacy requests.`, route: "/privacy/", body, graph: [breadcrumb([{name:"Home",route:"/"},{name:"Privacy",route:"/privacy/"}]), faqSchema(faqs)] });
}

function notFoundPage() { return page({ title: "Page Not Found", description: `The requested ${project.name} route could not be found. Return home or browse the service directory.`, route: "/404.html", body: `<main id="main-content" class="not-found"><div><span>404</span><h1>Page Not Found</h1><p>The requested route is not part of this ${esc(project.topicLower)} service map.</p><a class="button" href="/">Return Home</a><a href="/services/">Browse Services</a></div></main>` }); }
function favicon() { return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="14" fill="${project.palette.paper}"/><path d="M14 14h18v14h18v22H28V34H14V14Z" fill="none" stroke="${project.palette.teal}" stroke-width="7" stroke-linejoin="round"/><path d="M39 29v20" stroke="${project.palette.orange}" stroke-width="7" stroke-linecap="round"/></svg>`; }

resetGeneratedPages();
write("/", homePage());
write("/services/", servicesPage());
project.services.forEach((service) => write(serviceRoute(service), servicePage(service)));
write("/service-areas/", areasPage());
areas.forEach((area) => write(areaRoute(area), areaPage(area)));
for (const area of areas) for (const service of project.services) write(localRoute(service, area), localPage(service, area));
write("/process/", processPage());
write("/contact/", contactPage());
write("/privacy/", privacyPage());
write("/404.html", notFoundPage());
fs.writeFileSync(path.join(out, "assets", "favicon.svg"), favicon(), "utf8");
fs.writeFileSync(path.join(out, "sitemap.xml"), `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${routes.map((route) => `  <url><loc>${abs(route)}</loc></url>`).join("\n")}\n</urlset>\n`, "utf8");
fs.writeFileSync(path.join(out, "robots.txt"), config.indexingEnabled ? `User-agent: *\nAllow: /\nSitemap: ${abs("/sitemap.xml")}\n` : `User-agent: *\nDisallow: /\nSitemap: ${abs("/sitemap.xml")}\n`, "utf8");
console.log(`Generated ${routes.length + 1} HTML pages: ${project.services.length} services, ${areas.length} areas, and ${project.services.length * areas.length} matched city/service pages.`);
